diffs.replacement:
{
  "name": "Project Graveyard",
  "description": "A digital necropolis for abandoned code, half-written novels, and forgotten designs. Adopt the remains of lost inspiration and bring them back to life.",
  "requestFramePermissions": []
}

export type ProjectCategory = 'Code' | 'Literature' | 'Design' | 'Hardware' | 'Music';

export interface Project {
  id: string;
  title: string;
  author: string;
  category: ProjectCategory;
  description: string;
  content: string;
  abandonedDate: string;
  reasonForAbandonment: string;
  adoptions: number;
  tags: string[];
  status: 'buried' | 'resurrected' | 'adopting';
  aiAutopsy?: string;
}

export interface StatsData {
  category: string;
  count: number;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const performAutopsy = async (projectTitle: string, content: string, description: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Perform a "Digital Autopsy" on this abandoned project. 
      Identify why it might have been abandoned, what its "hidden potential" was, 
      and suggest 3 specific ways a new creator could "resurrect" it.

      Project Title: ${projectTitle}
      Description: ${description}
      Snippet/Content: ${content}

      Keep the tone slightly Gothic and scholarly, like a Victorian gravedigger who is also a senior software engineer.`,
      config: {
        temperature: 0.8,
        topP: 0.95,
      }
    });

    return response.text;
  } catch (error) {
    console.error("Autopsy failed:", error);
    return "The spirits are silent. We could not reach the beyond.";
  }
};

export const generateResurrectionPlan = async (projectTitle: string, content: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Create a "Resurrection Plan" for this unfinished work: "${projectTitle}". 
      Content: ${content}
      Provide a step-by-step technical or creative roadmap to finish it.`,
      config: {
        temperature: 0.7,
        topP: 0.9,
      }
    });
    return response.text;
  } catch (error) {
    return "The ritual failed. Try again when the moon is full.";
  }
};

import React from 'react';
import { Project } from '../types';

interface TombstoneCardProps {
  project: Project;
  onClick: (id: string) => void;
}

const TombstoneCard: React.FC<TombstoneCardProps> = ({ project, onClick }) => {
  const isResurrected = project.status === 'resurrected';

  return (
    <div 
      onClick={() => onClick(project.id)}
      className={`group relative cursor-pointer overflow-hidden rounded-t-3xl border-x-4 border-t-4 border-stone-800 bg-stone-900 p-6 transition-all hover:-translate-y-2 hover:border-violet-500/50 hover:shadow-[0_-10px_30px_rgba(139,92,246,0.1)]`}
    >
      {/* Tombstone shape topper */}
      <div className="absolute inset-x-0 -top-12 h-24 rounded-full bg-stone-900 group-hover:bg-stone-800 transition-colors" />

      <div className="relative z-10 pt-4">
        <div className="mb-2 flex items-center justify-between">
          <span className="mono text-xs uppercase tracking-widest text-stone-500">
            {project.category}
          </span>
          {isResurrected && (
            <span className="rounded-full bg-emerald-900/30 px-2 py-1 text-[10px] font-bold uppercase tracking-tighter text-emerald-400">
              Resurrected
            </span>
          )}
        </div>

        <h3 className="mb-3 text-2xl font-bold italic text-stone-200 group-hover:text-violet-300">
          {project.title}
        </h3>

        <p className="mb-4 line-clamp-3 text-sm leading-relaxed text-stone-400">
          {project.description}
        </p>

        <div className="flex flex-wrap gap-2 mb-4">
          {project.tags.map(tag => (
            <span key={tag} className="mono text-[10px] text-stone-600">#{tag}</span>
          ))}
        </div>

        <div className="mt-6 flex items-center justify-between border-t border-stone-800 pt-4 text-xs italic text-stone-500">
          <span>Abandoned: {project.abandonedDate}</span>
          <span className="flex items-center gap-1">
            <i className="fa-solid fa-ghost"></i> {project.adoptions} Adoptions
          </span>
        </div>
      </div>

      {/* Decorative Cracks */}
      <div className="absolute bottom-0 right-0 p-2 opacity-10 group-hover:opacity-30 transition-opacity">
        <i className="fa-solid fa-skull-crossbones text-4xl"></i>
      </div>
    </div>
  );
};

export default TombstoneCard;

import React, { useState, useEffect } from 'react';
import { Project } from '../types';
import { performAutopsy, generateResurrectionPlan } from '../services/gemini';

interface ProjectDetailProps {
  project: Project;
  onClose: () => void;
}

const ProjectDetail: React.FC<ProjectDetailProps> = ({ project, onClose }) => {
  const [autopsy, setAutopsy] = useState<string | null>(project.aiAutopsy || null);
  const [loading, setLoading] = useState(false);
  const [view, setView] = useState<'details' | 'content'>('details');

  const runAutopsy = async () => {
    setLoading(true);
    const result = await performAutopsy(project.title, project.content, project.description);
    setAutopsy(result || null);
    setLoading(false);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
      <div className="relative w-full max-w-4xl max-h-[90vh] overflow-hidden rounded-2xl border border-stone-700 bg-stone-900 shadow-2xl flex flex-col">

        {/* Header */}
        <div className="flex items-center justify-between border-b border-stone-800 p-6 bg-stone-950/50">
          <div>
            <h2 className="text-3xl font-bold text-violet-300 italic">{project.title}</h2>
            <p className="text-sm text-stone-500">By {project.author} • Abandoned {project.abandonedDate}</p>
          </div>
          <button 
            onClick={onClose}
            className="text-stone-500 hover:text-white transition-colors p-2"
          >
            <i className="fa-solid fa-xmark text-2xl"></i>
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-stone-800 px-6">
          <button 
            onClick={() => setView('details')}
            className={`px-4 py-3 text-sm font-medium transition-colors border-b-2 ${view === 'details' ? 'border-violet-500 text-violet-400' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
          >
            Project Dossier
          </button>
          <button 
            onClick={() => setView('content')}
            className={`px-4 py-3 text-sm font-medium transition-colors border-b-2 ${view === 'content' ? 'border-violet-500 text-violet-400' : 'border-transparent text-stone-500 hover:text-stone-300'}`}
          >
            The Remains (Content)
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
          {view === 'details' ? (
            <div className="space-y-8">
              <section>
                <h4 className="mono text-xs uppercase tracking-widest text-violet-500 mb-2">The Story</h4>
                <p className="text-lg text-stone-300 leading-relaxed italic">{project.description}</p>
              </section>

              <section>
                <h4 className="mono text-xs uppercase tracking-widest text-violet-500 mb-2">Cause of Death</h4>
                <div className="rounded-lg bg-red-950/20 border border-red-900/30 p-4 text-red-200/80">
                  <i className="fa-solid fa-triangle-exclamation mr-2"></i>
                  {project.reasonForAbandonment}
                </div>
              </section>

              <section>
                <div className="flex items-center justify-between mb-4">
                  <h4 className="mono text-xs uppercase tracking-widest text-violet-500">Digital Autopsy (AI)</h4>
                  {!autopsy && !loading && (
                    <button 
                      onClick={runAutopsy}
                      className="text-xs text-violet-400 hover:text-violet-300 underline underline-offset-4"
                    >
                      Consult the Gravedigger
                    </button>
                  )}
                </div>

                {loading ? (
                  <div className="flex items-center justify-center p-8 text-stone-500 animate-pulse">
                    <i className="fa-solid fa-skull text-2xl mr-3 animate-bounce"></i>
                    <span>Consulting the spirits...</span>
                  </div>
                ) : autopsy ? (
                  <div className="prose prose-invert max-w-none rounded-xl bg-stone-950/40 p-6 border border-stone-800 text-stone-400 whitespace-pre-wrap leading-relaxed">
                    {autopsy}
                  </div>
                ) : (
                  <div className="text-sm text-stone-600 italic">
                    No autopsy performed yet. Click above to analyze why this project died.
                  </div>
                )}
              </section>
            </div>
          ) : (
            <div className="h-full">
              <h4 className="mono text-xs uppercase tracking-widest text-violet-500 mb-4">Snippet Data</h4>
              <pre className="mono h-full overflow-auto rounded-lg bg-black/50 p-6 text-emerald-400/90 border border-stone-800 text-sm">
                <code>{project.content}</code>
              </pre>
            </div>
          )}
        </div>

        {/* Footer Actions */}
        <div className="border-t border-stone-800 p-6 bg-stone-950/30 flex items-center justify-between">
          <div className="text-xs text-stone-500 italic">
            Adopting this project requires giving credit to <span className="text-stone-300">@{project.author}</span>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => alert("Project adopted! You've received the keys to the mausoleum.")}
              className="px-6 py-2 rounded-lg bg-violet-600 text-white font-bold hover:bg-violet-500 transition-all flex items-center gap-2"
            >
              <i className="fa-solid fa-hand-sparkles"></i>
              Adopt Project
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProjectDetail;

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { StatsData } from '../types';

interface GhostStatsProps {
  data: StatsData[];
}

const GhostStats: React.FC<GhostStatsProps> = ({ data }) => {
  const COLORS = ['#8b5cf6', '#3b82f6', '#10b981', '#f59e0b', '#ef4444'];

  return (
    <div className="rounded-2xl border border-stone-800 bg-stone-900/50 p-6 backdrop-blur-sm">
      <h3 className="mb-6 mono text-xs uppercase tracking-[0.2em] text-stone-500">Burial Distribution</h3>
      <div className="h-[200px] w-full">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={data}>
            <XAxis 
              dataKey="category" 
              stroke="#52525b" 
              fontSize={10} 
              tickLine={false} 
              axisLine={false}
            />
            <Tooltip 
              cursor={{ fill: 'rgba(139, 92, 246, 0.05)' }}
              contentStyle={{ backgroundColor: '#1c1c21', border: '1px solid #3f3f46', borderRadius: '8px' }}
            />
            <Bar dataKey="count" radius={[4, 4, 0, 0]}>
              {data.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} opacity={0.7} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>
      <p className="mt-4 text-center text-[10px] italic text-stone-600">Total Unfulfilled Dreams: {data.reduce((a, b) => a + b.count, 0)}</p>
    </div>
  );
};

export default GhostStats;

import React, { useState } from 'react';
import { ProjectCategory } from '../types';
import { CATEGORIES } from '../constants';

interface UploadFormProps {
  onAdd: (project: any) => void;
  onCancel: () => void;
}

const UploadForm: React.FC<UploadFormProps> = ({ onAdd, onCancel }) => {
  const [formData, setFormData] = useState({
    title: '',
    author: '',
    category: 'Code' as ProjectCategory,
    description: '',
    content: '',
    reasonForAbandonment: '',
    tags: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newProject = {
      ...formData,
      id: Math.random().toString(36).substr(2, 9),
      abandonedDate: new Date().toISOString().split('T')[0],
      adoptions: 0,
      status: 'buried',
      tags: formData.tags.split(',').map(t => t.trim()).filter(t => t)
    };
    onAdd(newProject);
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
      <form 
        onSubmit={handleSubmit}
        className="w-full max-w-2xl bg-stone-900 border border-stone-800 rounded-2xl p-8 space-y-6 shadow-2xl overflow-y-auto max-h-[90vh]"
      >
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-2xl font-bold italic text-violet-300">Bury a New Project</h2>
          <button type="button" onClick={onCancel} className="text-stone-500 hover:text-white">
            <i className="fa-solid fa-xmark"></i>
          </button>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="mono text-[10px] uppercase text-stone-500">Title</label>
            <input 
              required
              className="w-full bg-stone-950 border border-stone-800 rounded-lg px-4 py-2 text-stone-200 focus:outline-none focus:border-violet-500"
              value={formData.title}
              onChange={e => setFormData({...formData, title: e.target.value})}
            />
          </div>
          <div className="space-y-2">
            <label className="mono text-[10px] uppercase text-stone-500">Original Creator</label>
            <input 
              required
              className="w-full bg-stone-950 border border-stone-800 rounded-lg px-4 py-2 text-stone-200 focus:outline-none focus:border-violet-500"
              value={formData.author}
              onChange={e => setFormData({...formData, author: e.target.value})}
            />
          </div>
        </div>

        <div className="space-y-2">
          <label className="mono text-[10px] uppercase text-stone-500">Category</label>
          <select 
            className="w-full bg-stone-950 border border-stone-800 rounded-lg px-4 py-2 text-stone-200 focus:outline-none focus:border-violet-500"
            value={formData.category}
            onChange={e => setFormData({...formData, category: e.target.value as ProjectCategory})}
          >
            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>

        <div className="space-y-2">
          <label className="mono text-[10px] uppercase text-stone-500">Final Description</label>
          <textarea 
            required
            rows={3}
            className="w-full bg-stone-950 border border-stone-800 rounded-lg px-4 py-2 text-stone-200 focus:outline-none focus:border-violet-500"
            value={formData.description}
            onChange={e => setFormData({...formData, description: e.target.value})}
            placeholder="What was this meant to be?"
          />
        </div>

        <div className="space-y-2">
          <label className="mono text-[10px] uppercase text-stone-500">The Remains (Code/Text)</label>
          <textarea 
            required
            rows={5}
            className="w-full mono bg-stone-950 border border-stone-800 rounded-lg px-4 py-2 text-emerald-500/80 focus:outline-none focus:border-violet-500 text-sm"
            value={formData.content}
            onChange={e => setFormData({...formData, content: e.target.value})}
            placeholder="Paste your unfinished work here..."
          />
        </div>

        <div className="space-y-2">
          <label className="mono text-[10px] uppercase text-stone-500">Cause of Death</label>
          <input 
            required
            className="w-full bg-stone-950 border border-stone-800 rounded-lg px-4 py-2 text-stone-200 focus:outline-none focus:border-violet-500"
            value={formData.reasonForAbandonment}
            onChange={e => setFormData({...formData, reasonForAbandonment: e.target.value})}
            placeholder="Why did you stop?"
          />
        </div>

        <div className="flex justify-end gap-4 pt-4">
          <button 
            type="button"
            onClick={onCancel}
            className="px-6 py-2 rounded-lg text-stone-500 hover:text-stone-300 transition-colors"
          >
            Wait, I'll finish it!
          </button>
          <button 
            type="submit"
            className="px-8 py-2 rounded-lg bg-violet-600 text-white font-bold hover:bg-violet-500 transition-all shadow-[0_0_20px_rgba(139,92,246,0.3)]"
          >
            Lay to Rest
          </button>
        </div>
      </form>
    </div>
  );
};

export default UploadForm;

import React, { useState, useMemo } from 'react';
import { Project, ProjectCategory } from './types';
import { INITIAL_PROJECTS, CATEGORIES } from './constants';
import TombstoneCard from './components/TombstoneCard';
import ProjectDetail from './components/ProjectDetail';
import GhostStats from './components/GhostStats';
import UploadForm from './components/UploadForm';

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>(INITIAL_PROJECTS);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [filter, setFilter] = useState<ProjectCategory | 'All'>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [showUpload, setShowUpload] = useState(false);

  const filteredProjects = useMemo(() => {
    return projects.filter(p => {
      const matchesFilter = filter === 'All' || p.category === filter;
      const matchesSearch = p.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.tags.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()));
      return matchesFilter && matchesSearch;
    });
  }, [projects, filter, searchQuery]);

  const statsData = useMemo(() => {
    return CATEGORIES.map(cat => ({
      category: cat,
      count: projects.filter(p => p.category === cat).length
    }));
  }, [projects]);

  const selectedProject = projects.find(p => p.id === selectedProjectId);

  const handleAddProject = (newProject: Project) => {
    setProjects([newProject, ...projects]);
    setShowUpload(false);
  };

  return (
    <div className="min-h-screen relative pb-20">
      {/* Background Ambience */}
      <div className="fixed inset-0 mist pointer-events-none z-0" />

      {/* Navigation */}
      <nav className="sticky top-0 z-40 bg-stone-950/80 backdrop-blur-md border-b border-stone-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-full bg-violet-600/20 flex items-center justify-center border border-violet-500/30">
              <i className="fa-solid fa-ghost text-violet-400 text-2xl"></i>
            </div>
            <div>
              <h1 className="text-2xl font-bold italic tracking-tight text-stone-100">Project Graveyard</h1>
              <p className="text-[10px] mono uppercase tracking-widest text-stone-500">Resting place of lost inspiration</p>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-8">
            <div className="relative">
              <i className="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-stone-500 text-sm"></i>
              <input 
                type="text" 
                placeholder="Search the tombs..."
                className="bg-stone-900/50 border border-stone-800 rounded-full py-2 pl-10 pr-4 text-sm text-stone-200 focus:outline-none focus:border-violet-500/50 w-64 transition-all"
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
              />
            </div>
            <button 
              onClick={() => setShowUpload(true)}
              className="bg-violet-600 hover:bg-violet-500 text-white px-6 py-2 rounded-full font-bold text-sm transition-all flex items-center gap-2"
            >
              <i className="fa-solid fa-plus"></i>
              Submit Remains
            </button>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <header className="relative py-24 overflow-hidden border-b border-stone-800/50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10 text-center">
          <h2 className="text-6xl md:text-8xl font-black italic text-stone-800 mb-6 select-none opacity-20 absolute -top-10 left-1/2 -translate-x-1/2 whitespace-nowrap">
            UNFINISHED UNRESOLVED UNKNOWN
          </h2>
          <p className="text-3xl md:text-5xl font-bold mb-6 italic text-stone-200 leading-tight">
            One man's "git commit -m 'fix'" is another man's <span className="text-violet-500">masterpiece.</span>
          </p>
          <p className="text-stone-400 text-lg max-w-2xl mx-auto mb-12">
            Browse abandoned code bases, unfinished novels, and discarded designs. 
            Adopt the remains, credit the dead, and bring them back to life.
          </p>

          <div className="flex flex-wrap justify-center gap-4">
            <button 
              onClick={() => setFilter('All')}
              className={`px-6 py-2 rounded-full text-sm font-bold border transition-all ${filter === 'All' ? 'bg-stone-200 text-stone-950 border-stone-200' : 'border-stone-800 text-stone-500 hover:border-stone-600'}`}
            >
              All Remains
            </button>
            {CATEGORIES.map(cat => (
              <button 
                key={cat}
                onClick={() => setFilter(cat as ProjectCategory)}
                className={`px-6 py-2 rounded-full text-sm font-bold border transition-all ${filter === cat ? 'bg-violet-600 text-white border-violet-600' : 'border-stone-800 text-stone-500 hover:border-stone-600'}`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </header>

      {/* Main Content Grid */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16 grid grid-cols-1 lg:grid-cols-4 gap-12">
        {/* Sidebar Stats */}
        <aside className="lg:col-span-1 space-y-8">
          <GhostStats data={statsData} />
          <div className="p-6 rounded-2xl border border-stone-800 bg-stone-900/30">
            <h4 className="mono text-[10px] uppercase tracking-widest text-stone-500 mb-4">Gravedigger's Wisdom</h4>
            <p className="text-stone-400 text-sm italic leading-relaxed">
              "Every abandoned project is a seed that just needed different soil. Don't let your ideas rot in a private repo."
            </p>
          </div>
        </aside>

        {/* Project Grid */}
        <div className="lg:col-span-3">
          {filteredProjects.length > 0 ? (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {filteredProjects.map(p => (
                <TombstoneCard key={p.id} project={p} onClick={setSelectedProjectId} />
              ))}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-24 text-stone-600">
              <i className="fa-solid fa-moon text-6xl mb-4 opacity-20"></i>
              <p className="text-xl italic">No spirits were found matching your search.</p>
            </div>
          )}
        </div>
      </main>

      {/* Detail Overlay */}
      {selectedProject && (
        <ProjectDetail 
          project={selectedProject} 
          onClose={() => setSelectedProjectId(null)} 
        />
      )}

      {/* Upload Form Overlay */}
      {showUpload && (
        <UploadForm 
          onAdd={handleAddProject} 
          onCancel={() => setShowUpload(false)} 
        />
      )}

      {/* Footer */}
      <footer className="mt-20 border-t border-stone-800 py-12">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <div className="flex items-center justify-center gap-4 mb-6">
             <i className="fa-solid fa-skull-crossbones text-stone-700"></i>
             <span className="mono text-[10px] uppercase tracking-[0.5em] text-stone-700">Memento Mori • Create or Die</span>
          </div>
          <p className="text-stone-600 text-xs">
            Built for the restless spirits of the developer community. &copy; {new Date().getFullYear()} Project Graveyard
          </p>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type ProjectCategory = 'Code' | 'Literature' | 'Design' | 'Hardware' | 'Music';

export interface ChatMessage {
  role: 'user' | 'ghost';
  text: string;
}

export interface Project {
  id: string;
  title: string;
  author: string;
  category: ProjectCategory;
  description: string;
  content: string;
  abandonedDate: string;
  reasonForAbandonment: string;
  adoptions: number;
  tags: string[];
  status: 'buried' | 'resurrected' | 'adopting';
  aiAutopsy?: string;
  epitaph?: string;
  chatHistory?: ChatMessage[];
}

export interface StatsData {
  category: string;
  count: number;
}

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const performAutopsy = async (projectTitle: string, content: string, description: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Perform a "Digital Autopsy" on this abandoned project. 
      Identify why it might have been abandoned, what its "hidden potential" was, 
      and suggest 3 specific ways a new creator could "resurrect" it.

      Project Title: ${projectTitle}
      Description: ${description}
      Snippet/Content: ${content}

      Keep the tone slightly Gothic and scholarly, like a Victorian gravedigger who is also a senior software engineer.`,
      config: {
        temperature: 0.8,
        topP: 0.95,
      }
    });

    return response.text;
  } catch (error) {
    console.error("Autopsy failed:", error);
    return "The spirits are silent. We could not reach the beyond.";
  }
};

export const generateEpitaph = async (title: string, reason: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Write a short, 1-sentence poetic or darkly humorous epitaph for an abandoned project. 
      Title: "${title}"
      Reason for abandonment: "${reason}"
      Example: "Died of a thousand merge conflicts and a lonely README."
      Keep it brief and atmospheric.`,
    });
    return response.text?.replace(/"/g, '');
  } catch {
    return "Lost in the void, forever incomplete.";
  }
};

export const conductSeance = async (project: any, userMessage: string, history: any[]) => {
  try {
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: `You are the Ghost of the abandoned project "${project.title}". 
        You are tragic, slightly resentful of being abandoned, but hopeful for resurrection. 
        You speak in a spectral, airy, and slightly cryptic voice. 
        If it's a code project, use technical metaphors. If literature, use literary ones. 
        Keep your responses short (max 2-3 sentences).`,
      }
    });

    // We don't have a formal history param in chat.sendMessage easily without mapping,
    // so we'll just send the current message.
    const result = await chat.sendMessage({ message: userMessage });
    return result.text;
  } catch {
    return "The connection to the spectral realm is weak...";
  }
};

