                <p className="text-[10px] font-black uppercase text-stone-100">{user.name}</p>
                <p className="text-[8px] mono text-violet-500 uppercase">{user.rank}</p>
              </div>
            </button>
          </div>
        </div>
      </nav>

      {view === 'graveyard' ? (
